<section id="visitor-sessions" class="app-panel admin-panel admin-card-pad admin-section-space"><div class="panel-heading"><div><p class="panel-kicker">SESSION HISTORY</p><h2>Sessions</h2></div><span class="panel-count"><?=number_format((int)($sessionData['total']??0))?> total</span></div><div class="admin-history-list"><?php foreach($sessions as $s):$sessionSeconds=max(0,(int)strtotime((string)$s['last_seen_at'].' UTC')-(int)strtotime((string)$s['first_seen_at'].' UTC'));$durationLabel=$sessionSeconds>=3600?floor($sessionSeconds/3600).'h '.floor(($sessionSeconds%3600)/60).'m':($sessionSeconds>=60?floor($sessionSeconds/60).'m '.($sessionSeconds%60).'s':$sessionSeconds.'s');?><div class="admin-history-item"><div><strong><?=htmlspecialchars(trim((string)($s['browser']??'Browser').' · '.(string)($s['os_name']??'OS').' · '.(string)($s['device_type']??''),' ·'),ENT_QUOTES,'UTF-8')?></strong><?=web_local_datetime($s['last_seen_at']??null,'—')?></div><p><?=(int)$s['pageview_count']?> pageview(s) · <?=$durationLabel?> duration · <?=htmlspecialchars((string)$s['ip_address'],ENT_QUOTES,'UTF-8')?> · <?=htmlspecialchars((string)$s['last_path'],ENT_QUOTES,'UTF-8')?></p></div><?php endforeach;?></div><?php if((int)($sessionData['pages']??1)>1):?><nav class="analytics-pagination"><span><?=number_format((int)$sessionData['total'])?> sessions</span><div><?php if((int)$sessionData['page']>1):?><a href="<?=htmlspecialchars(route_url('admin/visitor.php').'?'.http_build_query($sessionBase+['session_page'=>(int)$sessionData['page']-1]),ENT_QUOTES,'UTF-8')?>">← Previous</a><?php endif;?><strong>Page <?=(int)$sessionData['page']?> / <?=(int)$sessionData['pages']?></strong><?php if((int)$sessionData['page']<(int)$sessionData['pages']):?><a href="<?=htmlspecialchars(route_url('admin/visitor.php').'?'.http_build_query($sessionBase+['session_page'=>(int)$sessionData['page']+1]),ENT_QUOTES,'UTF-8')?>">Next →</a><?php endif;?></div></nav><?php endif;?></section>

<section id="visitor-journey" class="app-panel admin-panel admin-card-pad admin-section-space"><div class="panel-heading"><div><p class="panel-kicker">VISITOR JOURNEY</p><h2>Pages and events</h2><p class="admin-muted">Paginated instead of silently truncating history.</p></div><span class="panel-count"><?=number_format((int)($journeyData['total']??0))?> entries</span></div><nav class="visitor-journey-filters"><?php foreach(['all'=>'All','pages'=>'Pages','events'=>'Events','conversions'=>'Conversions'] as $kind=>$label):?><a class="<?=$journeyKind===$kind?'is-current':''?>" href="<?=htmlspecialchars(route_url('admin/visitor.php').'?'.http_build_query(['id'=>$visitorKey,'session_page'=>(int)($sessionData['page']??1),'journey_kind'=>$kind]),ENT_QUOTES,'UTF-8')?>"><?=$label?></a><?php endforeach;?></nav><div class="visitor-journey"><?php foreach($journey as $item):?><div class="visitor-journey-row <?=$item['kind']==='event'?'is-event':'is-page'?>"><span class="visitor-journey-mark"></span><div><strong><?=htmlspecialchars((string)$item['label'],ENT_QUOTES,'UTF-8')?></strong><?php if(!empty($item['path'])):?><small><?=htmlspecialchars((string)$item['path'],ENT_QUOTES,'UTF-8')?></small><?php endif;?><?php if($item['kind']==='event'&&!empty($item['metadata'])):?><small><?=htmlspecialchars(json_encode($item['metadata'],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?:'',ENT_QUOTES,'UTF-8')?></small><?php endif;?></div><?=web_local_datetime($item['occurred_at']??null,'—')?></div><?php endforeach;?><?php if(!$journey):?><p class="admin-muted">No matching journey entries recorded.</p><?php endif;?></div><?php if((int)($journeyData['pages']??1)>1):?><nav class="analytics-pagination"><span><?=number_format((int)$journeyData['total'])?> entries</span><div><?php if((int)$journeyData['page']>1):?><a href="<?=htmlspecialchars(route_url('admin/visitor.php').'?'.http_build_query($journeyBase+['journey_page'=>(int)$journeyData['page']-1]),ENT_QUOTES,'UTF-8')?>">← Previous</a><?php endif;?><strong>Page <?=(int)$journeyData['page']?> / <?=(int)$journeyData['pages']?></strong><?php if((int)$journeyData['page']<(int)$journeyData['pages']):?><a href="<?=htmlspecialchars(route_url('admin/visitor.php').'?'.http_build_query($journeyBase+['journey_page'=>(int)$journeyData['page']+1]),ENT_QUOTES,'UTF-8')?>">Next →</a><?php endif;?></div></nav><?php endif;?></section>
<?php admin_page_end(); ?>
